package com.thijs226.shortcircuit;
import java.util.*;
public final class CoreTests {
 static int passed,failed;
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static void test(String name,Runnable task){try{task.run();passed++;System.out.println("PASS "+name);}catch(Throwable e){failed++;System.out.println("FAIL "+name+": "+e);}}
 public static void main(String[] args){
  test("expired hourly minute exits on next swipe",()->{BlockPolicy p=new BlockPolicy();check(p.observe(true,false,false,true)==1,"consume free allowance");check(p.observe(true,false,false,false)==0,"finish current");check(p.observe(true,true,false,true)==2,"cannot refresh free allowance while in feed");});
  test("reentry during cooldown blocked",()->{BlockPolicy p=new BlockPolicy();p.observe(true,false,false,true);p.observe(false,false,false,false);check(p.observe(true,false,false,false)==2,"cooldown enforced");});
  test("reentry after cooldown allowed",()->{BlockPolicy p=new BlockPolicy();p.observe(true,false,false,true);p.observe(false,false,false,false);check(p.observe(true,false,false,true)==1,"new allowance");});
  test("pause expires only on next advance",()->{BlockPolicy p=new BlockPolicy();check(p.observe(true,false,true,false)==0,"paused entry");check(p.observe(true,true,true,false)==0,"paused scroll");check(p.observe(true,false,false,true)==0,"no mid-video kick");check(p.observe(true,true,false,true)==2,"expiry must not spend free allowance");});
  test("active break permits scrolling",()->{BlockPolicy p=new BlockPolicy();p.observe(true,false,false,true);check(p.observe(true,true,true,false)==0,"new pause overrides");});
  test("cooldown boundaries and duration mapping",()->{check(BlockPolicy.remaining(300001,1)==300000,"start");check(BlockPolicy.remaining(300001,300000)==1,"before");check(BlockPolicy.remaining(300001,300001)==0,"at");check(BlockPolicy.minutes(0)==2&&BlockPolicy.minutes(1)==5&&BlockPolicy.minutes(2)==7&&BlockPolicy.minutes(3)==10,"levels");});
  test("pipe connection accepts unused decoys",()->{MazeModel m=new MazeModel(3,new int[]{2,10,12,6,0,5,3,10,1});check(Arrays.equals(m.path(),new int[]{0,1,2,5,8}),"any connected path wins");});
  test("fixed endpoints and nonadjacent slides rejected",()->{MazeModel m=new MazeModel(3,new int[]{2,10,12,6,0,5,3,10,1});int[] before=m.cells();check(!m.move(0)&&!m.move(8)&&!m.move(2)&&!m.move(-1)&&!m.move(20),"illegal moves");check(Arrays.equals(before,m.cells()),"unchanged");});
  test("slide disconnect, undo reconnect and reset",()->{MazeModel m=new MazeModel(3,new int[]{2,10,12,6,0,5,3,10,1});check(m.move(1),"adjacent");check(m.path().length==0,"gap disconnects");check(m.moves()==1,"count");check(m.undo()&&m.path().length>0,"undo");m.move(1);m.reset();check(m.moves()==0&&m.path().length>0,"reset");});
  test("malformed maze rejected",()->{boolean rejected=false;try{new MazeModel(3,new int[9]);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"invalid fixed endpoints");});
  test("generated boards have difficulty-specific gaps and are unsolved",()->{for(int n=3;n<=6;n++)for(int seed=0;seed<180;seed++){MazeModel m=MazeModel.generate(n,12+(n-3)*20,new Random(seed));check(m.path().length==0,"not already solved "+n+"/"+seed);int zeros=0;for(int c:m.cells())if(c==0)zeros++;check(zeros==new int[]{1,2,4,6}[n-3],"gap count for size "+n+": "+zeros);check(Integer.bitCount(m.cells()[0])==1&&Integer.bitCount(m.cells()[n*n-1])==1,"fixed endpoint masks");}});
  test("generated easy mazes are reachable by legal slides",()->{for(int seed=0;seed<30;seed++){MazeModel m=MazeModel.generate(3,14,new Random(seed));ArrayDeque<int[]> q=new ArrayDeque<>();Set<String> seen=new HashSet<>();q.add(m.cells());boolean solved=false;while(!q.isEmpty()){int[] b=q.remove();if(!seen.add(Arrays.toString(b)))continue;MazeModel x=new MazeModel(3,b);if(x.path().length>0){solved=true;break;}for(int i=0;i<9;i++){MazeModel y=new MazeModel(3,b);if(y.move(i))q.add(y.cells());}}check(solved,"unreachable seed "+seed);}});
  test("normal homepage Shorts shelf is not player",()->{ShortsSignals s=new ShortsSignals();s.add("reel_item_thumbnail","Shorts",false,true);s.add("like_button","Like",false,true);s.add("share_button","Share",false,true);check(!s.player(),"shelf not player");});
  test("normal watch video is not Shorts",()->{ShortsSignals s=new ShortsSignals();s.add("player_view","",false,true);s.add("like_button","Like",false,true);s.add("dislike_button","Dislike",false,true);s.add("share_button","Share",false,true);check(!s.player(),"normal player");});
  test("visible reel pager detected across languages",()->{ShortsSignals s=new ShortsSignals();s.add("com.google.android.youtube:id/reel_recycler","",false,true);check(s.player(),"id detection");});
  test("invisible player nodes ignored",()->{ShortsSignals s=new ShortsSignals();s.add("reel_recycler","",false,false);check(!s.player(),"hidden");});
  test("comment list scroll never considered a feed swipe",()->{check(!ShortsSignals.feedScroll("comments_recycler", "RecyclerView",900,1000),"comment list");check(!ShortsSignals.feedScroll("reel_comments_list", "RecyclerView",900,1000),"reel comment list");check(ShortsSignals.feedScroll("reel_recycler", "RecyclerView",900,1000),"reel pager");check(!ShortsSignals.feedScroll("", "RecyclerView",900,1000),"unknown recycler");});
  test("scroll and following title update are one advance",()->{FeedTracker t=new FeedTracker();t.reset("first",0);check(t.observe("first",true,900)==900,"scroll event");check(t.observe("second",false,1100)<0,"title belongs to prior scroll");check(t.observe("second",false,1500)<0,"no second transition at expiry");check(t.observe("third",true,2200)==2200,"later swipe");});
  test("title-only advance retains its original time",()->{FeedTracker t=new FeedTracker();t.reset("first",0);check(t.observe("second",false,900)<0,"wait for stable metadata");check(t.observe("second",false,1300)==900,"attribute to first observation before expiry");});
  test("repeated scroll callbacks are debounced",()->{FeedTracker t=new FeedTracker();t.reset("first",0);check(t.observe("second",true,900)==900,"first event");check(t.observe("second",true,1020)<0,"duplicate callback");});
  test("restored redeemed or older puzzle cannot grant break",()->{check(BlockPolicy.mayRedeem(5,5,4),"new issued puzzle");check(!BlockPolicy.mayRedeem(5,5,5),"already redeemed");check(!BlockPolicy.mayRedeem(4,6,5),"older saved state");check(!BlockPolicy.mayRedeem(7,6,5),"not issued");check(!BlockPolicy.mayRedeem(0,6,0),"invalid id");});
  test("two gaps permit either explicit neighboring destination",()->{int[] b={2,0,12,0,10,5,3,10,1};MazeModel up=new MazeModel(3,b);check(up.gapCount()==2,"two gaps");check(up.move(4,1),"slide up");check(up.cells()[1]==10&&up.cells()[4]==0&&up.cells()[3]==0,"up destination respected");MazeModel left=new MazeModel(3,b);check(left.move(4,3),"slide left");check(left.cells()[3]==10&&left.cells()[1]==0,"left destination respected");});
  test("destinations enumerate only adjacent empty slots",()->{MazeModel m=new MazeModel(3,new int[]{2,0,12,0,10,5,3,10,1});int[] d=m.destinations(4);Arrays.sort(d);check(Arrays.equals(d,new int[]{1,3}),"both choices");check(m.destinations(0).length==0&&m.destinations(8).length==0,"fixed tiles");check(m.destinations(1).length==0,"empty slot cannot move");check(!m.move(1,3)&&!m.move(4,8)&&!m.move(4,6),"illegal targets rejected");});
  test("multi-gap undo and reset recover exact boards",()->{int[] b={2,0,12,0,10,5,3,10,1};MazeModel m=new MazeModel(3,b);check(m.move(4,1)&&m.move(6,3),"two slides");check(m.gapCount()==2&&m.moves()==2,"gap invariant and moves");check(m.undo()&&m.undo(),"undo both");check(Arrays.equals(b,m.cells())&&m.moves()==0,"full history reversal");m.move(4,3);m.reset();check(Arrays.equals(b,m.cells())&&m.gapCount()==2,"reset");});
  test("restored multi-gap board keeps initial reset state",()->{int[] initial={2,0,12,0,10,5,3,10,1};MazeModel first=new MazeModel(3,initial);first.move(4,1);MazeModel restored=new MazeModel(3,first.cells());restored.restoreInitial(initial,first.moves());check(restored.gapCount()==2&&restored.moves()==1,"restored state");restored.reset();check(Arrays.equals(initial,restored.cells()),"original reset layout");});
  test("generated multi-gap easy boards are legally solvable",()->{for(int seed=0;seed<16;seed++){MazeModel m=MazeModel.generate(3,2,20,new Random(seed));check(m.gapCount()==2,"requested gaps");ArrayDeque<int[]> q=new ArrayDeque<>();Set<String> seen=new HashSet<>();q.add(m.cells());boolean solved=false;while(!q.isEmpty()){int[] b=q.remove();if(!seen.add(Arrays.toString(b)))continue;MazeModel x=new MazeModel(3,b);if(x.path().length>0){solved=true;break;}for(int i=1;i<8;i++)for(int gap:x.destinations(i)){MazeModel y=new MazeModel(3,b);check(y.move(i,gap),"legal child");q.add(y.cells());}}check(solved,"unreachable multi-gap seed "+seed);}});
  test("random legal multi-gap slides reverse without losing tiles",()->{Random random=new Random(912);for(int n=3;n<=6;n++)for(int seed=0;seed<30;seed++){MazeModel m=MazeModel.generate(n,30,new Random(seed));int[] original=m.cells();int gaps=m.gapCount();int moved=0;for(int k=0;k<30;k++){List<int[]> options=new ArrayList<>();for(int i=1;i<n*n-1;i++)for(int gap:m.destinations(i))options.add(new int[]{i,gap});check(!options.isEmpty(),"movable board");int[] pick=options.get(random.nextInt(options.size()));check(m.move(pick[0],pick[1]),"legal slide");check(m.gapCount()==gaps,"gaps invariant");moved++;}while(moved-->0)check(m.undo(),"undo available");check(Arrays.equals(original,m.cells()),"exact recovery");}});
  test("expired hourly minute exits on alternate reel player scroll",()->{BlockPolicy p=new BlockPolicy();FeedTracker t=new FeedTracker();t.reset("",0);check(p.observe(true,false,false,true)==BlockPolicy.START_HOURLY,"hourly minute requested");ScrollSignal e=new ScrollSignal(1200,"android.view.ViewGroup",1,0,600);e.source("com.google.android.youtube:id/reel_watch_player","android.view.ViewGroup",1080,2100);long at=t.observe("",e.isFeed(true,false,1080,2400),e.position,e.at,1200);check(p.observe(true,at>=0,false,false)==BlockPolicy.BLOCK,"alternate player swipe must exit after the minute");});
  test("expired break exits on unnamed full screen recycler swipe",()->{BlockPolicy p=new BlockPolicy();FeedTracker t=new FeedTracker();t.reset("",0);p.observe(true,false,true,false);check(p.observe(true,false,false,true)==BlockPolicy.ALLOW,"finish current Short at expiry");ScrollSignal e=new ScrollSignal(5500,"androidx.recyclerview.widget.RecyclerView",2,0,700);e.source("","androidx.recyclerview.widget.RecyclerView",1080,2100);long at=t.observe("",e.isFeed(true,false,1080,2400),e.position,e.at,5500);check(p.observe(true,at>=0,at>=0&&at<5000,true)==BlockPolicy.BLOCK,"next swipe after expiry must block instead of spending free allowance");});
  test("unavailable source still detects pager in confirmed Shorts",()->{ScrollSignal e=new ScrollSignal(1000,"androidx.viewpager.widget.ViewPager",2,0,500);check(e.isFeed(true,false,1080,2400),"source-less pager fallback");check(!e.isFeed(false,false,1080,2400),"never outside Shorts");check(!e.isFeed(true,true,1080,2400),"never behind comments or sheets");});
  test("unavailable generic source is not assumed to be a swipe",()->{ScrollSignal e=new ScrollSignal(1000,"android.view.ViewGroup",-1,0,0);check(!e.isFeed(true,false,1080,2400),"unknown event ignored");});
  test("explicit reel pager with unavailable bounds is recognized",()->{ScrollSignal e=new ScrollSignal(1000,"android.view.ViewGroup",2,0,0);e.source("reel_recycler","android.view.ViewGroup",0,0);check(e.isFeed(true,false,1080,2400),"known pager ID survives empty bounds");});
  test("known pager still requires confirmed player context",()->{ScrollSignal e=new ScrollSignal(1000,"RecyclerView",2,0,500);e.source("reel_recycler","RecyclerView",1080,2100);check(!e.isFeed(false,false,1080,2400),"Home shelf not player");check(!e.isFeed(true,true,1080,2400),"sheet suppresses scroll");});
  test("comment ancestor overrides full screen reel container",()->{ScrollSignal e=new ScrollSignal(1000,"RecyclerView",8,0,500);e.source("","RecyclerView",1080,2100);e.source("comments_recycler","RecyclerView",1080,2100);e.source("reel_recycler","RecyclerView",1080,2400);check(!e.isFeed(true,false,1080,2400),"comment scrolling must not eject");});
  test("small nested carousel is not a Shorts advance",()->{ScrollSignal e=new ScrollSignal(1000,"RecyclerView",3,0,200);e.source("chips","RecyclerView",1080,120);e.source("reel_recycler","RecyclerView",1080,2400);check(!e.isFeed(true,false,1080,2400),"small child cannot borrow feed parent bounds");});
  test("horizontal pager movement is ignored",()->{ScrollSignal e=new ScrollSignal(1000,"RecyclerView",2,700,0);e.source("reel_recycler","RecyclerView",1080,2100);check(!e.isFeed(true,false,1080,2400),"horizontal movement is not vertical feed");});
  test("changed page index catches a quick first swipe",()->{FeedTracker t=new FeedTracker();t.reset("",0);check(t.observe("",true,0,100,100)<0,"initial layout primes position");check(t.observe("",true,1,300,300)==300,"actual index change during entry grace must count");});
  test("queued pre expiry swipe keeps event time",()->{FeedTracker t=new FeedTracker();BlockPolicy p=new BlockPolicy();t.reset("",0);p.observe(true,false,true,false);long at=t.observe("",true,1,900,1300);check(at==900,"original event time before break expiry");check(p.observe(true,at>=0,at<1000,false)==BlockPolicy.ALLOW,"queue delay must not interrupt current Short");check(p.observe(true,false,false,false)==BlockPolicy.ALLOW,"expiry itself does not interrupt");});
  test("long scroll callback burst is one advance across expiry",()->{FeedTracker t=new FeedTracker();t.reset("",0);check(t.observe("",true,1,900,900)==900,"first advance");check(t.observe("",true,1,1250,1250)<0,"same gesture");check(t.observe("",true,1,1600,1600)<0,"long animation stays coalesced");check(t.observe("",true,2,1800,1800)==1800,"next page index is a new advance");});
  test("new gesture works when YouTube reuses one item index",()->{FeedTracker t=new FeedTracker();t.reset("",0);check(t.observe("",true,0,900,900)==900,"first gesture");check(t.observe("",true,0,2400,2400)==2400,"later gesture at reused position");});
  test("ordinary video stays outside fallback detection",()->{ScrollSignal e=new ScrollSignal(1000,"RecyclerView",3,0,500);e.source("","RecyclerView",1080,2200);check(!e.isFeed(false,false,1080,2400),"ordinary video must not be blocked");});
  test("alternate Shorts title identifiers provide transition fallback",()->{check(ShortsSignals.videoTitleId("com.google.android.youtube:id/reel_player_header_title"),"header title");check(ShortsSignals.videoTitleId("com.google.android.youtube:id/shorts_video_title_text"),"Shorts title text");});
  test("channel sound and comment titles do not identify a new video",()->{for(String id:new String[]{"reel_channel_title","reel_audio_title","reel_comments_title","video_title","reel_description_title"})check(!ShortsSignals.videoTitleId(id),"not video metadata: "+id);});
  test("late index change in one swipe does not end break early",()->{FeedTracker t=new FeedTracker();BlockPolicy p=new BlockPolicy();t.reset("first",0);p.observe(true,false,true,false);long start=t.observe("first",true,0,900,900);check(start==900,"gesture starts before expiry");check(p.observe(true,start>=0,start<1000,false)==BlockPolicy.ALLOW,"pre-expiry advance allowed");long settle=t.observe("second",true,1,1100,1100);check(settle<0,"new index and title still belong to the 900ms gesture");check(p.observe(true,settle>=0,false,false)==BlockPolicy.ALLOW,"finish the Short after expiry");check(t.observe("third",true,2,1450,1450)==1450,"following page advance still detected");});
  test("continuous anonymous swipes cannot suppress expiry forever",()->{FeedTracker t=new FeedTracker();BlockPolicy p=new BlockPolicy();t.reset("",0);p.observe(true,false,true,false);long first=t.observe("",true,-1,900,900);p.observe(true,first>=0,first<1000,false);boolean blocked=false;for(long at=1200;at<=3000;at+=300){long advance=t.observe("",true,-1,at,at);if(p.observe(true,advance>=0,advance>=0&&advance<1000,false)==BlockPolicy.BLOCK){blocked=true;break;}}check(blocked,"missing metadata cannot create an unlimited break");});
  test("unavailable comment recycler source is ambiguous after dismissal",()->{ScrollSignal e=new ScrollSignal(1000,"androidx.recyclerview.widget.RecyclerView",5,0,400);check(!e.isFeed(true,false,1080,2400),"dismissed comments must not be promoted by the current player tree");});
  test("new title before index settlement remains one pre expiry swipe",()->{FeedTracker t=new FeedTracker();t.reset("first",0);t.observe("first",true,0,100,100);check(t.observe("second",true,0,900,1050)==900,"snapshot title can arrive before index settles");check(t.observe("second",true,1,1100,1100)<0,"late index still belongs to original gesture");});
  test("known unchanged video does not hit anonymous burst limit",()->{FeedTracker t=new FeedTracker();t.reset("first",0);check(t.observe("first",true,0,900,900)==900,"start");check(t.observe("second",true,1,1100,1100)<0,"settlement");for(long at:new long[]{1400,1700,2000,2300})check(t.observe("second",true,1,at,at)<0,"unchanged video at "+at);check(t.observe("third",true,2,2500,2500)==2500,"real following video still detected");});

  test("hourly grant provides sixty seconds and a rolling hour cooldown",()->{BreakTimers t=new BreakTimers(0,0,0);check(t.startHourly(1000,100000),"first grant available");check(t.pauseUntil()==61000,"exactly one minute");check(t.nextHourlyAt()==3601000&&t.hourlyWallAt()==3700000,"hour begins with grant");});
  test("active minute permits multiple Shorts without identity",()->{BreakTimers t=new BreakTimers(0,0,0);BlockPolicy p=new BlockPolicy();check(p.observe(true,false,false,true)==BlockPolicy.START_HOURLY,"request on entry");check(t.startHourly(1000,100000),"grant saved");for(long at:new long[]{1300,10000,60000})check(p.observe(true,true,t.activeAt(at),false)==BlockPolicy.ALLOW,"feed advance during minute at "+at);});
  test("reentering during minute keeps original deadline",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);BlockPolicy p=new BlockPolicy();p.observe(true,false,t.activeAt(1000),false);p.observe(false,false,false,false);check(p.observe(true,false,t.activeAt(30000),false)==BlockPolicy.ALLOW,"remaining minute allows reopening");check(!t.startHourly(30000,129000)&&t.pauseUntil()==61000,"reentry never resets deadline");});
  test("minute expiry finishes current Short then blocks next advance",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);BlockPolicy p=new BlockPolicy();p.observe(true,false,t.activeAt(60999),false);check(!t.activeAt(61000),"exact expiry");check(p.observe(true,false,t.activeAt(61000),false)==BlockPolicy.ALLOW,"finish current");check(p.observe(true,true,t.activeAt(61001),false)==BlockPolicy.BLOCK,"next advance exits");});
  test("reentry after minute cannot spend another hour allowance",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);BlockPolicy p=new BlockPolicy();check(!t.startHourly(61000,160000),"cooldown still active");check(p.observe(true,false,t.activeAt(61000),t.hourlyReady(61000))==BlockPolicy.BLOCK,"expired minute blocks fresh entry");check(t.nextHourlyAt()==3601000,"blocked attempt never shifts availability");});
  test("next grant available exactly sixty minutes after its start",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);check(!t.hourlyReady(3600999)&&!t.startHourly(3600999,3699999),"one millisecond early");check(t.hourlyReady(3601000)&&t.startHourly(3601000,3700000),"boundary eligible");check(t.pauseUntil()==3661000&&t.nextHourlyAt()==7201000,"fresh minute and fresh hour");});
  test("puzzle break does not spend unused hourly minute",()->{BreakTimers t=new BreakTimers(0,0,0);check(t.startPuzzle(1000,5),"puzzle reward");BlockPolicy p=new BlockPolicy();check(p.observe(true,false,t.activeAt(2000),t.hourlyReady(2000))==BlockPolicy.ALLOW,"puzzle pause takes priority");check(!t.startHourly(2000,100000)&&t.nextHourlyAt()==0,"no consumption or stacking");check(t.pauseUntil()==301000,"puzzle duration preserved");});
  test("puzzle reward during hourly cooldown preserves that cooldown",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);check(!t.startPuzzle(2000,10),"cannot stack active breaks");check(t.startPuzzle(70000,7),"puzzle still works during hourly cooldown");check(t.pauseUntil()==490000&&t.nextHourlyAt()==3601000,"puzzle duration and original hour");});
  test("ending a minute early does not refund or reset it",()->{BreakTimers t=new BreakTimers(0,0,0);t.startHourly(1000,100000);t.endPause();check(!t.activeAt(2000)&&!t.startHourly(2000,101000),"ended break stays spent");check(t.nextHourlyAt()==3601000,"same cooldown deadline");});
  test("recreated timers preserve minute and hourly deadlines",()->{BreakTimers t=new BreakTimers(61000,3601000,3700000);check(t.activeAt(60000)&&!t.activeAt(61000),"saved minute");check(!t.hourlyReady(3600999)&&t.hourlyReady(3601000),"saved hour");});
  test("reboot ends active pause but preserves bounded hour cooldown",()->{BreakTimers t=new BreakTimers(61000,3601000,3700000);t.afterReboot(500,160000);check(!t.activeAt(500)&&t.pauseUntil()==0,"no break survives reboot");check(t.nextHourlyAt()==3540500&&!t.hourlyReady(3540499)&&t.hourlyReady(3540500),"remaining fifty-nine minutes");});
  test("backward wall clock at reboot cannot exceed an hour cooldown",()->{BreakTimers t=new BreakTimers(61000,3601000,3700000);t.afterReboot(1000,1);check(t.nextHourlyAt()==3601000,"bounded to one hour");});
  test("elapsed wall deadline at reboot makes next minute ready",()->{BreakTimers t=new BreakTimers(61000,3601000,3700000);t.afterReboot(500,4000000);check(t.hourlyReady(500)&&t.startHourly(500,4000000),"old cooldown finished");});
  test("normal videos never request an hourly minute",()->{BlockPolicy p=new BlockPolicy();check(p.observe(false,true,false,true)==BlockPolicy.ALLOW,"outside confirmed Shorts");});
  test("old feed cannot auto renew when hourly cooldown finishes",()->{BlockPolicy p=new BlockPolicy();p.observe(true,false,true,false);check(p.observe(true,false,false,true)==BlockPolicy.ALLOW,"finish only current video");check(p.observe(true,true,false,true)==BlockPolicy.BLOCK,"must leave and reenter to start another minute");});
  test("pre expiry swipe handled after expiry keeps event time",()->{BreakTimers t=new BreakTimers(61000,3601000,3700000);FeedTracker f=new FeedTracker();f.reset("a",1000);BlockPolicy p=new BlockPolicy();p.observe(true,false,true,false);long at=f.observe("b",true,1,60900,61500);check(at==60900,"timestamp preserved");check(p.observe(true,at>=0,t.activeAt(at),false)==BlockPolicy.ALLOW,"queued pre-expiry swipe allowed");check(p.observe(true,false,t.activeAt(61500),false)==BlockPolicy.ALLOW,"no immediate kick after delayed event");check(p.observe(true,true,t.activeAt(62000),false)==BlockPolicy.BLOCK,"later swipe blocked");});
  System.out.println("RESULT "+passed+" passed, "+failed+" failed");if(failed>0)System.exit(1);
 }
}
